fn solve(input: Vec<i8>) -> Vec<&'static str> {
    let t = input[0] as usize; // The number of test cases
    let mut results = Vec::with_capacity(t);

    for &n in &input[1..=t] {
        let n = n as u32; // Convert to u32 for easier calculations

        if n == 1 {
            results.push("FastestFinger");
        } else if n == 2 {
            results.push("Ashishgup");
        } else if n & (n - 1) == 0 { // Check if n is a power of two
            results.push("FastestFinger");
        } else if n % 4 != 2 { // Check if n mod 4 is not equal to 2
            results.push("Ashishgup");
        } else { // n mod 4 == 2
            let p = n / 2;
            if is_limited_prime(p) {
                results.push("FastestFinger");
            } else {
                results.push("Ashishgup");
            }
        }
    }

    results
}

// Helper function to check if a number is a limited-prime
fn is_limited_prime(p: u32) -> bool {
    if p <= 1 {
        return false;
    }
    if p == 2 {
        return true;
    }
    if p % 2 == 0 {
        return false; // Even numbers greater than 2 are not prime
    }
    // Check for odd factors from 3 to sqrt(p)
    let limit = (p as f64).sqrt() as u32;
    for i in (3..=limit).step_by(2) {
        if p % i == 0 {
            return false;
        }
    }
    true
}